#!/usr/bin/env node
// Regenerates everything derived from the app listing and the published versions:
//   apps/<app>/latest/   copy of the newest version
//   apps/<app>/README.md app page in the standard layout (docs/app-page-standard.md)
//   README.md            app list between the apps:start / apps:end markers
//
// Usage: node scripts/generate.mjs          write files
//        node scripts/generate.mjs --check  exit 1 if any generated file is out of date
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import {
  APPS_DIR,
  BUTTON_IMAGE,
  PACKAGE_FILES,
  deployUrl,
  isPrerelease,
  latestOf,
  listDirs,
  readJson,
  versionsOf,
} from "./lib.mjs";

const check = process.argv.includes("--check");
const START = "<!-- apps:start -->";
const END = "<!-- apps:end -->";
const NOTICE =
  "<!-- Generated by scripts/generate.mjs from app.json, architecture.mmd and azuredeploy.json. Do not edit by hand. -->";

const outputs = new Map(); // path -> content
const removals = []; // generated files that must no longer exist

const button = (dir) => `[![Deploy to Azure](${BUTTON_IMAGE})](${deployUrl(dir)})`;
const cell = (v) => String(v ?? "").replace(/\r?\n/g, " ").replace(/\|/g, "\\|").trim();
const bullets = (items) => items.map((i) => `- ${i}`);

function table(header, rows) {
  return [`| ${header.join(" | ")} |`, `|${header.map(() => "---").join("|")}|`, ...rows.map((r) => `| ${r.map(cell).join(" | ")} |`)];
}

function paramDefault(p) {
  const type = String(p.type ?? "").toLowerCase();
  if (type.startsWith("secure")) return "";
  if (p.defaultValue === undefined) return "";
  const v = typeof p.defaultValue === "string" ? p.defaultValue : JSON.stringify(p.defaultValue);
  return `\`${v.length > 60 ? `${v.slice(0, 57)}...` : v}\``;
}

function parametersSection(template) {
  const params = Object.entries(template.parameters ?? {});
  if (!params.length) return ["This application has no deployment parameters.", ""];
  return [
    "The portal form fills these in; the table is for reference and scripted deployments.",
    "",
    ...table(
      ["Parameter", "Type", "Required", "Default", "Description"],
      params.map(([name, p]) => [
        `\`${name}\``,
        p.type,
        p.defaultValue === undefined ? "yes" : "no",
        paramDefault(p),
        p.metadata?.description ?? "",
      ]),
    ),
    "",
  ];
}

function outputsSection(template) {
  const outs = Object.entries(template.outputs ?? {});
  if (!outs.length) return [];
  return [
    "Deployment outputs (Azure portal > resource group > Deployments):",
    "",
    ...table(["Output", "Type", "Description"], outs.map(([n, o]) => [`\`${n}\``, o.type, o.metadata?.description ?? ""])),
    "",
  ];
}

function appReadme(app, appDir, meta, versions, latest) {
  const template = latest ? readJson(join(appDir, latest, "azuredeploy.json")) : {};
  const diagram = readFileSync(join(appDir, "architecture.mmd"), "utf8").trim();
  const L = [NOTICE, "", `# ${meta.title}`, "", meta.summary.trim(), ""];

  if (latest) {
    L.push(button(`${APPS_DIR}/${app}/latest`), "", `Version **${latest}** · [all versions](#versions)`, "");
  } else {
    L.push("No version published yet.", "");
  }

  L.push("## Overview", "", meta.description.trim(), "", "### Features", "", ...bullets(meta.features), "");

  if (meta.screenshots?.length) {
    L.push("## Screenshots", "");
    for (const s of meta.screenshots) L.push(`![${s.caption}](${s.file})`, "", `_${s.caption}_`, "");
  }

  L.push(
    "## Architecture",
    "",
    meta.architecture.description.trim(),
    "",
    "```mermaid",
    diagram,
    "```",
    "",
    "### Resources created in your subscription",
    "",
    ...table(
      ["Resource", "Azure type", "Purpose", "SKU / plan"],
      meta.architecture.resources.map((r) => [r.name, `\`${r.type}\``, r.purpose, r.sku ?? ""]),
    ),
    "",
  );

  L.push("## Requirements", "", ...bullets(meta.requirements), "");
  L.push("## Cost", "", meta.cost.trim(), "");
  L.push("## Security and data", "", meta.security.trim(), "");

  if (latest) L.push(`## Deployment parameters (version ${latest})`, "", ...parametersSection(template));

  const after = [...(latest ? outputsSection(template) : [])];
  if (meta.afterDeployment?.length) after.push(...meta.afterDeployment.map((s, i) => `${i + 1}. ${s}`), "");
  if (after.length) L.push("## After deployment", "", ...after);

  const s = meta.support ?? {};
  const links = [];
  if (s.homepage) links.push(`Product page: ${s.homepage}`);
  if (s.docs) links.push(`Documentation: ${s.docs}`);
  if (s.marketplaceUrl) links.push(`Azure Marketplace: ${s.marketplaceUrl}`);
  if (s.contact) links.push(`Contact: ${s.contact}`);
  if (links.length) L.push("## Support", "", ...bullets(links), "");

  L.push("## Versions", "");
  if (versions.length) {
    L.push(
      ...table(
        ["Version", "Deploy", "Files", "Release notes"],
        versions.map((v) => [
          isPrerelease(v) ? `${v} (preview)` : v,
          button(`${APPS_DIR}/${app}/${v}`),
          `[azuredeploy.json](${v}/azuredeploy.json), [createUiDefinition.json](${v}/createUiDefinition.json)`,
          existsSync(join(appDir, v, "release-notes.md")) ? `[notes](${v}/release-notes.md)` : "",
        ]),
      ),
      "",
    );
  } else {
    L.push("None yet.", "");
  }
  return L.join("\n");
}

const rows = [];
for (const app of listDirs(APPS_DIR)) {
  const appDir = join(APPS_DIR, app);
  if (!existsSync(join(appDir, "app.json")) || !existsSync(join(appDir, "architecture.mmd"))) {
    console.error(`skip ${appDir}: listing incomplete (validate.mjs reports this)`);
    continue;
  }
  const meta = readJson(join(appDir, "app.json"));
  const versions = versionsOf(appDir);
  const latest = latestOf(versions);
  if (latest) {
    for (const file of PACKAGE_FILES) {
      outputs.set(join(appDir, "latest", file), readFileSync(join(appDir, latest, file), "utf8"));
    }
  }
  // latest/ holds only the package files, even if the newest version has release notes.
  for (const extra of ["release-notes.md"]) removals.push(join(appDir, "latest", extra));
  outputs.set(join(appDir, "README.md"), appReadme(app, appDir, meta, versions, latest));
  rows.push([
    `[${meta.title}](${APPS_DIR}/${app}/README.md)`,
    meta.summary,
    latest ?? "-",
    latest ? button(`${APPS_DIR}/${app}/latest`) : "-",
  ]);
}

const appTable = rows.length
  ? table(["Application", "Description", "Version", "Deploy"], rows).join("\n")
  : "_No applications published yet._";
const rootReadme = readFileSync("README.md", "utf8");
const s = rootReadme.indexOf(START);
const e = rootReadme.indexOf(END);
if (s < 0 || e < s) {
  console.error(`README.md must contain ${START} and ${END}`);
  process.exit(1);
}
outputs.set(
  "README.md",
  `${rootReadme.slice(0, s + START.length)}\n${NOTICE}\n\n${appTable}\n\n${rootReadme.slice(e)}`,
);

let stale = 0;
for (const [path, content] of outputs) {
  const current = existsSync(path) ? readFileSync(path, "utf8") : null;
  if (current === content) continue;
  if (check) {
    console.error(`out of date: ${path}`);
    stale++;
  } else {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content);
    console.log(`wrote ${path}`);
  }
}
for (const path of removals) {
  if (!existsSync(path)) continue;
  if (check) {
    console.error(`should not exist: ${path}`);
    stale++;
  } else {
    rmSync(path);
    console.log(`removed ${path}`);
  }
}
if (stale) {
  console.error(`\n${stale} generated file(s) out of date. Run: node scripts/generate.mjs`);
  process.exit(1);
}
